files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #1e1e2f;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.app {
  background: #2a2a3c;
  border-radius: 1.5rem;
  padding: 2rem;
  max-width: 800px;
  width: 100%;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  font-size: 2rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
  color: #ffffff;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b8;
  margin-bottom: 2rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.color-box {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 1rem;
  border: 2px solid rgba(255, 255, 255, 0.1);
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.hex {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 0.875rem;
  letter-spacing: 0.05em;
  color: #e0e0e0;
  user-select: all;
}

.lock-btn {
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 0.5rem;
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  color: #a0a0b8;
  cursor: pointer;
  transition: all 0.15s ease;
  font-family: inherit;
}

.lock-btn:hover {
  border-color: #a0a0b8;
  color: #e0e0e0;
}

.lock-btn:focus-visible {
  outline: 2px solid #7c6fef;
  outline-offset: 2px;
}

.lock-btn[aria-pressed="true"] {
  background: #7c6fef;
  border-color: #7c6fef;
  color: #ffffff;
}

.lock-btn:active {
  transform: scale(0.95);
}

.generate-btn {
  background: #7c6fef;
  border: none;
  border-radius: 0.75rem;
  padding: 0.75rem 2rem;
  font-size: 1.125rem;
  font-weight: 600;
  color: #ffffff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  font-family: inherit;
  width: 100%;
  max-width: 300px;
}

.generate-btn:hover {
  background: #6a5cd4;
}

.generate-btn:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 2px;
}

.generate-btn:active {
  transform: scale(0.98);
  background: #5a4cc0;
}

@media (max-width: 600px) {
  .app {
    padding: 1.5rem;
  }
  .palette {
    grid-template-columns: repeat(3, 1fr);
  }
  .palette .swatch:nth-child(4),
  .palette .swatch:nth-child(5) {
    grid-column: span 1;
  }
}

@media (max-width: 400px) {
  .palette {
    grid-template-columns: repeat(2, 1fr);
  }
  .palette .swatch:nth-child(5) {
    grid-column: span 2;
    max-width: 50%;
    margin: 0 auto;
  }
  h1 {
    font-size: 1.5rem;
  }
  .hex {
    font-size: 0.75rem;
  }
}

(function() {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  const NUM_COLORS = 5;
  let colors = [];
  let locked = new Array(NUM_COLORS).fill(false);

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = n => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`.toUpperCase();
  }

  function generateHarmoniousPalette() {
    const baseHue = Math.floor(Math.random() * 360);
    const schemes = ['analogous', 'complementary', 'triadic', 'split'];
    const scheme = schemes[Math.floor(Math.random() * schemes.length)];
    const hues = [];

    for (let i = 0; i < NUM_COLORS; i++) {
      let hue;
      const offset = i - Math.floor(NUM_COLORS / 2);
      switch (scheme) {
        case 'analogous':
          hue = (baseHue + offset * 30 + 360) % 360;
          break;
        case 'complementary':
          hue = (baseHue + (i % 2 === 0 ? 0 : 180) + offset * 10 + 360) % 360;
          break;
        case 'triadic':
          hue = (baseHue + (i % 3) * 120 + offset * 5 + 360) % 360;
          break;
        case 'split':
          hue = (baseHue + (i % 3 === 0 ? 0 : i % 3 === 1 ? 150 : 210) + offset * 5 + 360) % 360;
          break;
      }
      const sat = 60 + Math.random() * 30;
      const light = 40 + Math.random() * 30;
      hues.push(hslToHex(Math.round(hue), Math.round(sat), Math.round(light)));
    }
    return hues;
  }

  function render() {
    paletteEl.innerHTML = '';
    colors.forEach((hex, i) => {
      const swatch = document.createElement('div');
      swatch.className = 'swatch';

      const box = document.createElement('div');
      box.className = 'color-box';
      box.style.backgroundColor = hex;
      box.setAttribute('aria-label', `Color ${i + 1}: ${hex}`);

      const hexLabel = document.createElement('span');
      hexLabel.className = 'hex';
      hexLabel.textContent = hex;

      const lockBtn = document.createElement('button');
      lockBtn.className = 'lock-btn';
      lockBtn.type = 'button';
      lockBtn.setAttribute('aria-pressed', locked[i] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', locked[i] ? `Unlock color ${i + 1}` : `Lock color ${i + 1}`);
      lockBtn.textContent = locked[i] ? 'Locked' : 'Lock';

      lockBtn.addEventListener('click', () => {
        locked[i] = !locked[i];
        render();
      });

      swatch.appendChild(box);
      swatch.appendChild(hexLabel);
      swatch.appendChild(lockBtn);
      paletteEl.appendChild(swatch);
    });
  }

  function generate() {
    const newColors = generateHarmoniousPalette();
    colors = newColors.map((hex, i) => locked[i] ? colors[i] : hex);
    render();
  }

  generateBtn.addEventListener('click', generate);

  // Initial palette
  colors = generateHarmoniousPalette();
  render();
})();
